    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    { const nr = await scwin.tx_fn_searchList(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil55800/jldfil55800.xml"); } };
    /* sdd-asis-lifecycle:end */
